      const halves = host.split('::');
      if (halves.length > 2) return false;
      const groups = halves.flatMap(part => part ? part.split(':') : []);
      if (groups.some(group => !/^[0-9a-f]{1,4}$/i.test(group))) return false;
      if (halves.length === 1 ? groups.length !== 8 : groups.length >= 8) return false;
    } else {
      const parts = /^([^:]+)(?::(\d+))?$/.exec(authority);
      if (!parts) return false;
      host = parts[1]; port = parts[2];
      if (host.length > 253) return false;
      const labels = host.replace(/\.$/, '').split('.');
      if (!labels.every(label => label.length > 0 && label.length <= 63 && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label))) return false;
      if (labels.every(label => /^\d+$/.test(label)) && (labels.length !== 4 || labels.some(label => Number(label) > 255))) return false;
